      }
      case 0x07: { // BGTZ
        if ((this.r[rs] | 0) > 0) { this.executeDelayAndJump(delayPC, (curPC + 4 + (simm << 2)) >>> 0); return; }
        break;
      }
      case 0x08: { // ADDI (treat as ADDIU, no trap)
        this.setReg(rt, (this.r[rs] + simm) | 0);
        break;
      }
      case 0x09: { // ADDIU
        this.setReg(rt, (this.r[rs] + simm) | 0);
        break;
      }
      case 0x0a: { // SLTI
        this.setReg(rt, ((this.r[rs] | 0) < simm) ? 1 : 0);
        break;
      }
      case 0x0b: { // SLTIU
        this.setReg(rt, ((this.r[rs] >>> 0) < ((simm >>> 0))) ? 1 : 0);
        break;
      }
      case 0x0c: { // ANDI
        this.setReg(rt, (this.r[rs] & imm) >>> 0);
        break;
      }
      case 0x0d: { // ORI
        this.setReg(rt, (this.r[rs] | imm) >>> 0);
        break;
      }
      case 0x0e: { // XORI
        this.setReg(rt, (this.r[rs] ^ imm) >>> 0);
        break;
      }
      case 0x0f: { // LUI
        this.setReg(rt, (imm << 16) >>> 0);
        break;
      }
      case 0x10: // COP0
        // ignore cop0 mostly
        break;
      case 0x11: // COP1 FPU
        this.execFPU(inst, curPC);
        break;
      case 0x12: case 0x13: // COP2/COP3 ignore
        break;
      case 0x14: { // BEQL
        if ((this.r[rs] | 0) === (this.r[rt] | 0)) { this.executeDelayAndJump(delayPC, (curPC + 4 + (simm << 2)) >>> 0); return; }
        else this.pc = (curPC + 8) >>> 0; // skip delay slot
        break;
      }
      case 0x15: { // BNEL
        if ((this.r[rs] | 0) !== (this.r[rt] | 0)) { this.executeDelayAndJump(delayPC, (curPC + 4 + (simm << 2)) >>> 0); return; }
        else this.pc = (curPC + 8) >>> 0;
        break;
      }
      case 0x16: { // BLEZL
        if ((this.r[rs] | 0) <= 0) { this.executeDelayAndJump(delayPC, (curPC + 4 + (simm << 2)) >>> 0); return; }
        else this.pc = (curPC + 8) >>> 0;
        break;
      }
      case 0x17: { // BGTZL
        if ((this.r[rs] | 0) > 0) { this.executeDelayAndJump(delayPC, (curPC + 4 + (simm << 2)) >>> 0); return; }
        else this.pc = (curPC + 8) >>> 0;
        break;
      }
      case 0x20: { // LB
        const v = this.mem.readU8((this.r[rs] + simm) >>> 0);
        this.setReg(rt, signExtend8(v));
        break;
      }
      case 0x21: { // LH
        const v = this.mem.readU16((this.r[rs] + simm) >>> 0);
        this.setReg(rt, signExtend16(v));
        break;
      }
      case 0x23: { // LW
        const v = this.mem.readU32((this.r[rs] + simm) >>> 0);
        this.setReg(rt, v);
        break;
      }
      case 0x24: { // LBU
        const v = this.mem.readU8((this.r[rs] + simm) >>> 0);
        this.setReg(rt, v);
        break;
      }
      case 0x25: { // LHU
        const v = this.mem.readU16((this.r[rs] + simm) >>> 0);
        this.setReg(rt, v);
        break;
      }
      case 0x28: { // SB
        this.mem.writeU8((this.r[rs] + simm) >>> 0, this.r[rt] & 0xff);
        break;
      }
      case 0x29: { // SH
        this.mem.writeU16((this.r[rs] + simm) >>> 0, this.r[rt] & 0xffff);
        break;
      }
      case 0x2b: { // SW
        this.mem.writeU32((this.r[rs] + simm) >>> 0, this.r[rt] >>> 0);
        break;
      }
      case 0x2f: { // CACHE - ignore
        break;
      }
      case 0x30: { // LL - treat as LW
        const v = this.mem.readU32((this.r[rs] + simm) >>> 0);
        this.setReg(rt, v);
        break;
      }
      case 0x31: { // LWC1
        const v = this.mem.readU32((this.r[rs] + simm) >>> 0);
        this.f[rt] = new Float32Array(Buffer.from([v&0xff,(v>>8)&0xff,(v>>16)&0xff,(v>>>24)&0xff]).buffer)[0];
        this.d[rt] = this.f[rt];
        break;
      }
      case 0x35: { // LDC1
        const lo = this.mem.readU32((this.r[rs] + simm) >>> 0);
        const hi = this.mem.readU32((this.r[rs] + simm + 4) >>> 0);
        const buf = Buffer.from([lo&0xff,(lo>>8)&0xff,(lo>>16)&0xff,(lo>>>24)&0xff, hi&0xff,(hi>>8)&0xff,(hi>>16)&0xff,(hi>>>24)&0xff]);
        this.d[rt] = buf.readDoubleLE(0);
        break;
      }
      case 0x38: { // SWC1
        const idx = rt;
        const buf = Buffer.alloc(4);
        buf.writeFloatLE(this.f[idx], 0);
        const v = buf.readUInt32LE(0);
        this.mem.writeU32((this.r[rs] + simm) >>> 0, v);
        break;
      }
      case 0x3d: { // SDC1
        const idx = rt;
        const buf = Buffer.alloc(8);
        buf.writeDoubleLE(this.d[idx], 0);
        const lo = buf.readUInt32LE(0);
        const hi = buf.readUInt32LE(4);
        this.mem.writeU32((this.r[rs] + simm) >>> 0, lo);
        this.mem.writeU32((this.r[rs] + simm + 4) >>> 0, hi);
        break;
      }
      default:
        this.halt(`unknown opcode 0x${op.toString(16)} inst=0x${inst.toString(16)} pc=0x${curPC.toString(16)}`);
        return;
    }

    // If we didn't branch, advance to delay slot / next
    this.pc = (curPC + 4) >>> 0;
  }

  executeDelayAndJump(delayPC, target) {
    const inst = this.mem.readU32(delayPC);
    this.execute(inst, delayPC);
    if (this.running) this.pc = target >>> 0;
  }

  execSpecial(inst, curPC) {
    const funct = inst & 0x3f;
    const rs = (inst >> 21) & 0x1f;
    const rt = (inst >> 16) & 0x1f;
    const rd = (inst >> 11) & 0x1f;
    const shamt = (inst >> 6) & 0x1f;
    const sa = (shamt);
    switch (funct) {
      case 0x00: // SLL
        this.setReg(rd, (this.r[rt] << shamt) | 0);
        break;
      case 0x02: // SRL
        this.setReg(rd, (this.r[rt] >>> shamt) >>> 0);
        break;
      case 0x03: // SRA
        this.setReg(rd, (this.r[rt] >> shamt) | 0);
        break;
      case 0x04: // SLLV
        this.setReg(rd, (this.r[rt] << (this.r[rs] & 0x1f)) | 0);
        break;
      case 0x06: // SRLV
        this.setReg(rd, (this.r[rt] >>> (this.r[rs] & 0x1f)) >>> 0);
        break;
      case 0x07: // SRAV
        this.setReg(rd, (this.r[rt] >> (this.r[rs] & 0x1f)) | 0);
        break;
      case 0x08: { // JR
        const target = this.r[rs] >>> 0;
        this.executeDelayAndJump((curPC + 4) >>> 0, target);
        break;
      }
      case 0x09: { // JALR
        const target = this.r[rs] >>> 0;
        this.setReg(rd === 0 ? 31 : rd, (curPC + 8) >>> 0);
        this.executeDelayAndJump((curPC + 4) >>> 0, target);
        break;
      }
      case 0x0c: // SYSCALL
        this.syscall();
        if (this.running) this.pc = (curPC + 4) >>> 0;
        break;
      case 0x0d: // BREAK
        this.halt(`BREAK at 0x${curPC.toString(16)}`);
        break;
      case 0x10: { // MFHI
        this.setReg(rd, this.hi);
        break;
      }
      case 0x11: { // MTHI
        this.hi = this.r[rs];
        break;
      }
      case 0x12: { // MFLO
        this.setReg(rd, this.lo);
        break;
      }
      case 0x13: { // MTLO
        this.lo = this.r[rs];
        break;
      }
      case 0x18: { // MULT
        const a = this.r[rs] | 0;
        const b = this.r[rt] | 0;
      let product = BigInt(a) * BigInt(b);
        const u = BigInt.asUintN(64, product);
        this.lo = Number(u & 0xffffffffn) | 0;
        this.hi = Number((u >> 32n) & 0xffffffffn) | 0;
        break;
      }
      case 0x19: { // MULTU
        const a = this.r[rs] >>> 0;
        const b = this.r[rt] >>> 0;
        let product = BigInt(a) * BigInt(b);
        const u = BigInt.asUintN(64, product);
        this.lo = Number(u & 0xffffffffn) | 0;
        this.hi = Number((u >> 32n) & 0xffffffffn) | 0;
        break;
      }
      case 0x1a: { // DIV
        const a = this.r[rs] | 0;
        const b = this.r[rt] | 0;
        if (b === 0) { this.lo = 0; this.hi = 0; }
        else {
          this.lo = (Math.trunc(a / b)) | 0;
          this.hi = (a - (this.lo * b)) | 0;
        }
        break;
      }
      case 0x1b: { // DIVU
        const a = this.r[rs] >>> 0;
        const b = this.r[rt] >>> 0;
        if (b === 0) { this.lo = 0; this.hi = 0; }
        else {
          this.lo = (a / b) >>> 0;
          this.hi = (a - (this.lo * b)) >>> 0;
        }
        break;
      }
      case 0x20: // ADD (no trap)
        this.setReg(rd, (this.r[rs] + this.r[rt]) | 0);
        break;
      case 0x21: // ADDU
        this.setReg(rd, (this.r[rs] + this.r[rt]) | 0);
        break;
      case 0x22: // SUB
        this.setReg(rd, (this.r[rs] - this.r[rt]) | 0);
        break;
      case 0x23: { // SUBU
        this.setReg(rd, (this.r[rs] - this.r[rt]) | 0);
        break;
      }
      case 0x24: { // AND
        this.setReg(rd, (this.r[rs] & this.r[rt]) >>> 0);
        break;
      }
      case 0x25: { // OR
        this.setReg(rd, (this.r[rs] | this.r[rt]) >>> 0);
        break;
      }
      case 0x26: { // XOR
        this.setReg(rd, (this.r[rs] ^ this.r[rt]) >>> 0);
        break;
      }
      case 0x27: { // NOR
        this.setReg(rd, ~(this.r[rs] | this.r[rt]) >>> 0);
        break;
      }
      case 0x2a: { // SLT
        this.setReg(rd, ((this.r[rs] | 0) < (this.r[rt] | 0)) ? 1 : 0);
        break;
      }
      case 0x2b: { // SLTU
        this.setReg(rd, ((this.r[rs] >>> 0) < (this.r[rt] >>> 0)) ? 1 : 0);
        break;
      }
      case 0x30: { // TGE - ignore traps mostly, but if triggering, halt
        if ((this.r[rs] | 0) >= (this.r[rt] | 0)) this.halt(`TGE at 0x${curPC.toString(16)}`);
        break;
      }
      case 0x31: { // TGEU
        if ((this.r[rs] >>> 0) >= (this.r[rt] >>> 0)) this.halt(`TGEU at 0x${curPC.toString(16)}`);
        break;
      }
      case 0x32: { // TLT - typically trap if less than; we ignore
        break;
      }
      case 0x33: { // TLTU - ignore
        break;
      }
      case 0x34: { // TEQ - could be division by zero trap; ignore to avoid halting
        break;
      }
      case 0x36: { // TNE
        break;
      }
      case 0x0f: { // SYNC - no-op
        break;
      }
      case 0x25: { // already OR above; keep for safety
        break;
      }
      // SEB / SEH (MIPS32r2)
      case 0x20+0: break;
      default:
        if (funct === 0x25) break; // OR duplicate
        this.halt(`unknown special funct 0x${funct.toString(16)} inst=0x${inst.toString(16)} pc=0x${curPC.toString(16)}`);
        break;
    }
  }

  execRegimm(inst, curPC) {
    const rt = (inst >> 16) & 0x1f;
    const rs = (inst >> 21) & 0x1f;
    const imm = inst & 0xffff;
    const simm = (imm & 0x8000) ? ((imm | 0xffff0000) | 0) : (imm & 0xffff);
    const target = (curPC + 4 + (simm << 2)) >>> 0;
    const delayPC = (curPC + 4) >>> 0;
    switch (rt) {
      case 0x00: { // BLTZ
        if ((this.r[rs] | 0) < 0) { this.executeDelayAndJump(delayPC, target); return; }
        break;
      }
      case 0x01: { // BGEZ
        if ((this.r[rs] | 0) >= 0) { this.executeDelayAndJump(delayPC, target); return; }
        break;
      }
      case 0x02: { // BLTZL
        if ((this.r[rs] | 0) < 0) { this.executeDelayAndJump(delayPC, target); return; }
        else this.pc = (curPC + 8) >>> 0;
        break;
      }
      case 0x03: { // BGEZL
        if ((this.r[rs] | 0) >= 0) { this.executeDelayAndJump(delayPC, target); return; }
        else this.pc = (curPC + 8) >>> 0;
        break;
      }
      case 0x10: { // BLTZAL
        this.setReg(31, (curPC + 8) >>> 0);
        if ((this.r[rs] | 0) < 0) { this.executeDelayAndJump(delayPC, target); return; }
        break;
      }
      case 0x11: { // BGEZAL
        this.setReg(31, (curPC + 8) >>> 0);
        if ((this.r[rs] | 0) >= 0) { this.executeDelayAndJump(delayPC, target); return; }
        break;
      }
      case 0x12: { // BLTZALL
        this.setReg(31, (curPC + 8) >>> 0);
        if ((this.r[rs] | 0) < 0) { this.executeDelayAndJump(delayPC, target); return; }
        else this.pc = (curPC + 8) >>> 0;
        break;
      }
      case 0x13: { // BGEZALL
        this.setReg(31, (curPC + 8) >>> 0);
        if ((this.r[rs] | 0) >= 0) { this.executeDelayAndJump(delayPC, target); return; }
        else this.pc = (curPC + 8) >>> 0;
        break;
      }
      default:
        this.halt(`unknown REGIMM rt 0x${rt.toString(16)} inst=0x${inst.toString(16)} pc=0x${curPC.toString(16)}`);
        break;
    }
  }

  execFPU(inst, curPC) {
    const fmt = (inst >> 21) & 0x1f;
    const rt = (inst >> 16) & 0x1f;
    const rd = (inst >> 11) & 0x1f;
    const fs = (inst >> 11) & 0x1f;
    const ft = (inst >> 16) & 0x1f;
    const fd = (inst >> 6) & 0x1f; // incorrect; fd is bits 6-10
    const funct = inst & 0x3f;
    const cc = (inst >> 18) & 0x7;

    // Correct field decoding for fpu arithmetic: fmt in bits 21-25, ft in 16-20, fs in 11-15, fd in 6-10
    const fdReal = (inst >> 6) & 0x1f;
    const fsReal = (inst >> 11) & 0x1f;
    const ftReal = (inst >> 16) & 0x1f;

    if ((inst & (1<<25)) || fmt !== 0 && fmt !== 0x10 && fmt !== 0x11 && fmt !== 0x14 && fmt !== 0x15) {
      // Some COP1 instructions have fmt=0 for MFC1 etc
    }

    // Determine if it's MFC1/CFC1/CTC1/MTC1/LDC1/SDC1/BC and arithmetic
    // Actually op=0x11 covers all COP1. We already handled LWC1/LDC1/SWC1/SDC1 in main switch.
    // Here handle MFC1, CFC1, MTC1, CTC1, BC, and arithmetic.
    const sub = (inst >> 21) & 0x1f;
    if (sub === 0) { // MFC1
      const buf = Buffer.alloc(4);
      buf.writeFloatLE(this.f[rt], 0);
      this.setReg(rt, buf.readInt32LE(0));
      return;
    } else if (sub === 4) { // MTC1
      const buf = Buffer.alloc(4);
      buf.writeInt32LE(this.r[rt] | 0, 0);
      this.f[rt] = buf.readFloatLE(0);
      this.d[rt] = this.f[rt];
      return;
    } else if (sub === 2) { // CFC1 - return FCSR for reg 31/0
      this.setReg(rt, this.fcsr);
      return;
    } else if (sub === 6) { // CTC1
      this.fcsr = this.r[rt];
      return;
    } else if (sub === 8) { // BC1
      const cc = (inst >> 18) & 0x7;
      const tf = (inst >> 16) & 0x1;
      const nd = (inst >> 16) & 0x1;
      // BC1T if bit 16 = 1, BC1F if 0? Actually: BC1F: nd=1; BC1T: nd=0 tf=1
      // Format: nd(tf) where tf is bit 16
      const branch = (this.fcc[cc] === ((inst >> 16) & 1)) ^ 0 ? ((inst >> 16) & 1) : 0;
      // Simpler: BC1F: branch if cc == 0; BC1T: branch if cc == 1
      const isTrue = (inst >> 16) & 1;
      const cond = this.fcc[cc] === (isTrue ? 1 : 0);
      const target = (curPC + 4 + (((inst & 0xffff) & 0x8000) ? ((inst & 0xffff) | 0xffff0000) : (inst & 0xffff)) << 2) >>> 0;
      const delayPC = (curPC + 4) >>> 0;
      if (cond) { this.executeDelayAndJump(delayPC, target); return; }
      else return;
    } else {
      // Arithmetic
      const isSingle = (fmt === 0x10);
      const isDouble = (fmt === 0x11);
      const isWord = (fmt === 0x14);
      switch (funct) {
        case 0x00: // ADD.S/ADD.D
          if (isSingle) this.f[fdReal] = this.f[fsReal] + this.f[ftReal];
          else if (isDouble) this.d[fdReal] = this.d[fsReal] + this.d[ftReal];
          break;
        case 0x01: // SUB.S/SUB.D
          if (isSingle) this.f[fdReal] = this.f[fsReal] - this.f[ftReal];
          else if (isDouble) this.d[fdReal] = this.d[fsReal] - this.d[ftReal];
          break;
        case 0x02: // MUL.S/MUL.D
          if (isSingle) this.f[fdReal] = this.f[fsReal] * this.f[ftReal];
          else if (isDouble) this.d[fdReal] = this.d[fsReal] * this.d[ftReal];
          break;
        case 0x03: // DIV.S/DIV.D
          if (isSingle) this.f[fdReal] = this.f[fsReal] / this.f[ftReal];
          else if (isDouble) this.d[fdReal] = this.d[fsReal] / this.d[ftReal];
          break;
        case 0x04: // SQRT.S/SQRT.D
          if (isSingle) this.f[fdReal] = Math.sqrt(this.f[fsReal]);
          else if (isDouble) this.d[fdReal] = Math.sqrt(this.d[fsReal]);
          break;
        case 0x05: // ABS.S/ABS.D
          if (isSingle) this.f[fdReal] = Math.abs(this.f[fsReal]);
          else if (isDouble) this.d[fdReal] = Math.abs(this.d[fsReal]);
          break;
        case 0x06: // MOV.S/MOV.D
          if (isSingle) this.f[fdReal] = this.f[fsReal];
          else if (isDouble) this.d[fdReal] = this.d[fsReal];
          break;
        case 0x07: // NEG.S/NEG.D
          if (isSingle) this.f[fdReal] = -this.f[fsReal];
          else if (isDouble) this.d[fdReal] = -this.d[fsReal];
          break;
        case 0x08: { // ROUND.L.S etc - for word conversion
          if (isSingle) { const v = Math.round(this.f[fsReal]); this.d[fdReal] = v; }
          else if (isDouble) { const v = Math.round(this.d[fsReal]); this.d[fdReal] = v; }
          break;
        }
        case 0x09: { // TRUNC.L.S etc - for word: trunc.w.s
          if (isSingle) { const v = Math.trunc(this.f[fsReal]); this.f[fdReal] = v; }
          else if (isDouble) { const v = Math.trunc(this.d[fsReal]); this.d[fdReal] = v; }
          break;
        }
        case 0x12: { // MOVZ
          if ((this.r[rt] | 0) === 0) { if (isSingle) this.f[fdReal]=this.f[fsReal]; else this.d[fdReal]=this.d[fsReal]; }
          break;
        }
        case 0x13: { // MOVN
          if ((this.r[rt] | 0) !== 0) { if (isSingle) this.f[fdReal]=this.f[fsReal]; else this.d[fdReal]=this.d[fsReal]; }
          break;
        }
        case 0x20: { // CVT.S.D / CVT.S.W etc
          if (isWord) this.f[fdReal] = this.f[fsReal]; // already float? We need word in f as int rep
          else if (isDouble) this.f[fdReal] = this.d[fsReal];
        }
          break;
        case 0x21: { // CVT.D.S/W
          if (isSingle) this.d[fdReal] = this.f[fsReal];
          else if (isWord) {
            const buf = Buffer.alloc(4);
            buf.writeFloatLE(this.f[fsReal], 0);
            const wv = buf.readInt32LE(0);
            this.d[fdReal] = wv;
          }
          break;
        }
        case 0x24: { // CVT.W.S/D - convert to int32 stored as float bits
          if (isSingle) {
            const v = Math.trunc(this.f[fsReal]);
            const buf = Buffer.alloc(4);
            buf.writeInt32LE(v | 0, 0);
            this.f[fdReal] = buf.readFloatLE(0);
          } else if (isDouble) {
            const v = Math.trunc(this.d[fsReal]);
            const buf = Buffer.alloc(4);
            buf.writeInt32LE(v | 0, 0);
            this.f[fdReal] = buf.readFloatLE(0);
          }
          break;
        }
        case 0x32: { // C.EQ.S/D
          { if (isSingle) this.fcc[cc] = (this.f[fsReal] === this.f[ftReal]) ? 1 : 0;
            else this.fcc[cc] = (this.d[fsReal] === this.d[ftReal]) ? 1 : 0; }
          break;
        }
        case 0x33: { // C.LT.S/D
          { if (isSingle) this.fcc[cc] = (this.f[fsReal] < this.f[ftReal]) ? 1 : 0;
            else this.fcc[cc] = (this.d[fsReal] < this.d[ftReal]) ? 1 : 0; }
          break;
        }
        case 0x34: { // C.LE.S/D
          { if (isSingle) this.fcc[cc] = (this.f[fsReal] <= this.f[ftReal]) ? 1 : 0;
            else this.fcc[cc] = (this.d[fsReal] <= this.d[ftReal]) ? 1 : 0; }
          break;
        }
        case 0x3c: { // C.LT with false? (F) - skip
          break;
        }
        case 0x3d: { // C.NGE (F) - skip
          break;
        }
        case 0x3e: { // C.LE with false? - skip
          break;
        }
        default:
          this.halt(`unknown FPU funct 0x${funct.toString(16)} inst=0x${inst.toString(16)} pc=0x${curPC.toString(16)} fmt=0x${fmt.toString(16)}`);
          break;
      }
    }
  }

  halt(msg) {
    this.running = false;
    console.error(`[vm] HALT: ${msg} instCount=${this.instCount} pc=0x${this.pc.toString(16)}`);
    console.error('registers:', Array.from(this.r).map((v,i)=>`r${i}=${v>>>0}`));
  }
}

// ---------- ELF Loader ----------
function loadELF(mem, path) {
  const buf = fs.readFileSync(path);
  // 32-bit LE ELF
  const e_type = buf.readUInt16LE(16);
  const e_machine = buf.readUInt16LE(18);
  if (e_machine !== 8) throw new Error(`Not MIPS: e_machine=${e_machine}`);
  const e_entry = buf.readUInt32LE(24);
